#include <iostream>
#include <cstdlib>
#include <string>

int main(int argc, char** argv) {
    long seed = 0;
    int n = 5;
    int l = 10;
    int chrom_size = 100;

    if (argc > 1) seed = atol(argv[1]);
    if (argc > 2) chrom_size = atoi(argv[2]);
    if (argc > 3) l = atoi(argv[3]);
    if (argc > 4) n = atoi(argv[4]);

    // Method 1: srand48 + drand48
    srand48(seed);
    std::cout << "Method 1 (srand48/drand48, pos=int(drand48()*(size-l))):" << std::endl;
    for (int i = 0; i < n; i++) {
        int start = (int)(drand48() * (chrom_size - l));
        double strand_r = drand48();
        char strand = (strand_r >= 0.5) ? '+' : '-';
        std::cout << "chr1\t" << start << "\t" << (start+l) << "\t" << (i+1) << "\t" << l << "\t" << strand << std::endl;
    }

    // Method 2: srand + rand
    srand(seed);
    std::cout << "Method 2 (srand/rand, pos=rand()%(size-l)):" << std::endl;
    for (int i = 0; i < n; i++) {
        int start = rand() % (chrom_size - l);
        int strand_r = rand();
        char strand = (strand_r % 2 == 0) ? '+' : '-';
        std::cout << "chr1\t" << start << "\t" << (start+l) << "\t" << (i+1) << "\t" << l << "\t" << strand << std::endl;
    }

    return 0;
}
