#!/usr/bin/env python3
"""
bedtools reimplementation in Python
"""

import sys
import os
import gzip
import math
import re
import random
import bisect
import argparse
from collections import defaultdict, OrderedDict

VERSION = "b2e3657"

# ============================================================================
# File format detection and parsing
# ============================================================================

def detect_file_format(filename):
    """Detect if file is BED, GFF, VCF, or BAM based on extension/content."""
    if filename == 'stdin' or filename == '-':
        return 'bed'  # Default for stdin

    name = filename.lower()
    if name.endswith('.bam') or name.endswith('.cram'):
        return 'bam'
    if name.endswith('.vcf') or name.endswith('.vcf.gz'):
        return 'vcf'
    if name.endswith('.gff') or name.endswith('.gff.gz') or \
       name.endswith('.gff3') or name.endswith('.gff3.gz') or \
       name.endswith('.gtf') or name.endswith('.gtf.gz'):
        return 'gff'
    return 'bed'

def open_file(filename):
    """Open a file, handling gzip and stdin."""
    if filename == 'stdin' or filename == '-':
        return sys.stdin
    if filename.endswith('.gz') or filename.endswith('.bgz'):
        return gzip.open(filename, 'rt')
    return open(filename, 'r')

class Interval:
    """Represents a genomic interval in 0-based half-open [start, end)."""
    __slots__ = ['chrom', 'start', 'end', 'fields', 'fmt']

    def __init__(self, chrom, start, end, fields=None, fmt='bed'):
        self.chrom = chrom
        self.start = start  # 0-based
        self.end = end      # 0-based half-open
        self.fields = fields or []  # original fields
        self.fmt = fmt

    def __repr__(self):
        return f"Interval({self.chrom}, {self.start}, {self.end})"

    def length(self):
        return self.end - self.start

    def to_string(self):
        """Return original string representation."""
        return '\t'.join(self.fields)

    def overlap(self, other):
        """Return overlap length with another interval (0 if no overlap)."""
        if self.chrom != other.chrom:
            return 0
        return max(0, min(self.end, other.end) - max(self.start, other.start))

    def overlaps(self, other, min_overlap=1e-9):
        """Return True if this interval overlaps other."""
        if self.chrom != other.chrom:
            return False
        ovl = max(0, min(self.end, other.end) - max(self.start, other.start))
        return ovl >= min_overlap

    def strand(self):
        """Get strand from fields."""
        if self.fmt == 'gff' and len(self.fields) >= 7:
            return self.fields[6]
        elif self.fmt == 'vcf':
            return '+'
        else:  # BED
            if len(self.fields) >= 6:
                return self.fields[5]
        return '.'

def parse_bed_line(line, fmt='auto'):
    """Parse a single line and return an Interval."""
    line = line.rstrip('\n\r')
    fields = line.split('\t')

    if not fields or not fields[0]:
        return None

    # Skip header/comment lines
    if fields[0].startswith('#') or fields[0].startswith('track') or \
       fields[0].startswith('browser') or fields[0].startswith('@'):
        return None

    # Auto-detect format if not specified
    if fmt == 'auto':
        # Check if it looks like VCF (CHROM POS ID REF ALT ...)
        # Check if it looks like GFF
        if len(fields) >= 3:
            try:
                int(fields[1])
                if len(fields) >= 5 and (fields[3] == '.' or all(c in 'ACGTNacgtn' for c in fields[3])):
                    fmt = 'vcf'
                elif len(fields) >= 8:
                    # Could be GFF if field 2 is source, field 3 is feature type
                    fmt = 'bed'
                else:
                    fmt = 'bed'
            except (ValueError, IndexError):
                return None
        else:
            return None

    try:
        if fmt == 'gff':
            # GFF is 1-based inclusive
            chrom = fields[0]
            start = int(fields[3]) - 1  # Convert to 0-based
            end = int(fields[4])        # Already exclusive in 0-based
            return Interval(chrom, start, end, fields, 'gff')
        elif fmt == 'vcf':
            # VCF POS is 1-based
            chrom = fields[0]
            pos = int(fields[1])
            # Check for END= in INFO field for SVs
            end = pos  # default: SNP, 0-based [pos-1, pos)
            if len(fields) >= 8 and fields[7] != '.':
                m = re.search(r'END=(\d+)', fields[7])
                if m:
                    end = int(m.group(1))
            start = pos - 1  # 0-based
            return Interval(chrom, start, end, fields, 'vcf')
        else:  # BED (0-based half-open)
            chrom = fields[0]
            start = int(fields[1])
            end = int(fields[2])
            return Interval(chrom, start, end, fields, 'bed')
    except (ValueError, IndexError):
        return None

def parse_file(filename, fmt='auto'):
    """Parse a file and yield Intervals."""
    if fmt == 'auto':
        fmt_to_use = detect_file_format(filename)
    else:
        fmt_to_use = fmt

    try:
        f = open_file(filename)
        for line in f:
            line = line.rstrip('\n\r')
            if not line:
                continue
            if line.startswith('#') or line.startswith('track') or \
               line.startswith('browser') or line.startswith('@'):
                yield line, True  # header line
                continue

            interval = parse_bed_line(line, fmt_to_use)
            if interval is not None:
                yield interval, False

        if f is not sys.stdin:
            f.close()
    except FileNotFoundError:
        print(f"Error: file {filename} not found", file=sys.stderr)
        sys.exit(1)

def read_genome(genome_file):
    """Read a genome file and return OrderedDict of {chrom: size}."""
    genome = OrderedDict()
    with open(genome_file) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) >= 2:
                try:
                    genome[parts[0]] = int(parts[1])
                except ValueError:
                    pass
    return genome

def read_intervals(filename, fmt='auto'):
    """Read all intervals from a file, filtering out headers."""
    intervals = []
    for item, is_header in parse_file(filename, fmt):
        if not is_header:
            intervals.append(item)
    return intervals

def format_interval(ivl, null_str=None):
    """Return formatted string for an interval."""
    return '\t'.join(ivl.fields)

def null_interval(fmt='bed', ncols=3):
    """Create a null/empty interval for no-hit reporting."""
    if fmt == 'bed':
        fields = ['.', '-1', '-1'] + ['.'] * max(0, ncols - 3)
    elif fmt == 'gff':
        fields = ['.', '.', '.', '-1', '-1', '.', '.', '.', '.']
    elif fmt == 'vcf':
        fields = ['.', '-1', '.', '.', '.', '-1', '.', '.']
    else:
        fields = ['.', '-1', '-1'] + ['.'] * max(0, ncols - 3)
    return Interval('.', -1, -1, fields, fmt)

# ============================================================================
# Interval overlap utilities
# ============================================================================

def check_overlap_fraction(a, b, f_a=1e-9, f_b=1e-9, recip=False, either=False):
    """Check if overlap fraction requirements are met."""
    ovl = a.overlap(b)
    if ovl <= 0:
        return False

    len_a = max(1, a.end - a.start)
    len_b = max(1, b.end - b.start)

    frac_a = ovl / len_a
    frac_b = ovl / len_b

    if recip:
        return frac_a >= f_a and frac_b >= f_a
    elif either:
        return frac_a >= f_a or frac_b >= f_b
    else:
        return frac_a >= f_a and frac_b >= f_b

def overlaps_with_fractions(a, b, f_a=1e-9, f_b=1e-9, recip=False, either=False):
    """Check overlap considering fraction requirements and strand."""
    if a.chrom != b.chrom:
        return False
    if a.start >= b.end or b.start >= a.end:
        return False
    return check_overlap_fraction(a, b, f_a, f_b, recip, either)

# ============================================================================
# Sweep line / interval intersection algorithms  
# ============================================================================

class IntervalIndex:
    """Simple interval index for fast overlap queries."""

    def __init__(self, intervals):
        """Build index from list of intervals."""
        # Group by chromosome
        self.chrom_intervals = defaultdict(list)
        for ivl in intervals:
            self.chrom_intervals[ivl.chrom].append(ivl)

        # Sort each chromosome's intervals by start
        for chrom in self.chrom_intervals:
            self.chrom_intervals[chrom].sort(key=lambda x: (x.start, x.end))

    def query(self, ivl):
        """Return list of intervals that overlap ivl."""
        chrom_list = self.chrom_intervals.get(ivl.chrom, [])
        if not chrom_list:
            return []

        results = []
        # Binary search for start position
        starts = [x.start for x in chrom_list]
        # Find first interval that could overlap
        # An interval overlaps if start < ivl.end and end > ivl.start
        idx = bisect.bisect_left(starts, ivl.end)

        for i in range(idx):
            b = chrom_list[i]
            if b.end > ivl.start:
                results.append(b)

        return results

