    """Read a genome file and return OrderedDict of {chrom: size}."""
    genome = OrderedDict()
    with open(genome_file) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) >= 2:
                try:
