def null_b_fields(bfmt, b_intervals_by_file):
    if not b_intervals_by_file: return ['.', '-1', '-1']
    bfmt = detect_fmt(b_intervals_by_file[0][0])
    if bfmt == 'gff': return ['.', '.', '.', '-1', '-1', '.', '.', '.', '.']
    if bfmt == 'vcf': return ['.', '-1', '.', '.', '.', '-1', '.', '.']
    # Determine number of columns from first interval
    first_ivls = b_intervals_by_file[0][1]
    if first_ivls:
        ncols = len(first_ivls[0].fields)
        return ['.', '-1', '-1'] + ['.']*(ncols-3)
    return ['.', '-1', '-1']

def cmd_intersect(args):
    p = argparse.ArgumentParser(add_help=False)
    p.add_argument('-a'); p.add_argument('-b', nargs='+'); p.add_argument('-wa', action='store_true')
    p.add_argument('-wb', action='store_true'); p.add_argument('-loj', action='store_true')
    p.add_argument('-wo', action='store_true'); p.add_argument('-wao', action='store_true')
