    p.add_argument('-C', action='store_true'); p.add_argument('-v', action='store_true')
    p.add_argument('-ubam', action='store_true'); p.add_argument('-s', action='store_true')
    p.add_argument('-S', action='store_true'); p.add_argument('-f', type=float, default=1e-9)
    p.add_argument('-F', type=float, default=1e-9); p.add_argument('-r', action='store_true', dest='recip')
    p.add_argument('-e', action='store_true', dest='either'); p.add_argument('-split', action='store_true')
    p.add_argument('-g'); p.add_argument('-nonamecheck', action='store_true')
    p.add_argument('-sorted', action='store_true'); p.add_argument('-names', nargs='+')
    p.add_argument('-filenames', action='store_true'); p.add_argument('-sortout', action='store_true')
    p.add_argument('-bed', action='store_true'); p.add_argument('-header', action='store_true')
    p.add_argument('-nobuf', action='store_true'); p.add_argument('-iobuf')
    p.add_argument('-abam')

    if not args:
        print_tool_header('intersect', 'intersectBed', 'Report overlaps between two feature files.')
        return

