    a_file = o.a or o.abam
    if not a_file or not o.b:
        print_tool_header('intersect', 'intersectBed', 'Report overlaps between two feature files.')
        return

    b_files = o.b
    b_data = []
    for bf in b_files:
        ivls = read_intervals(bf, detect_fmt(bf))
        b_data.append((bf, ivls))
